DO $ddl$ DECLARE r record;d text;t text; BEGIN FOR r IN SELECT p.oid FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND pg_get_functiondef(p.oid) LIKE '%colab_v_%' AND p.prokind='f' LOOP d:=pg_get_functiondef(r.oid); FOREACH t IN ARRAY ARRAY['legado_acertos_consultora','legado_maleta_categorias','legado_maleta_vendidos','legado_representantes','legado_acertos_praca','legado_consultoras','legado_maleta_status','legado_remessas','legado_maletas','legado_pracas','legado_notas','consultant_profiles','party_addresses','contact_points','party_roles','party_links','parties','remessas','kit_cycles','cob_pracas'] LOOP d:=replace(d,quote_literal('colab_v_'||t),quote_literal(t)); END LOOP; EXECUTE d; END LOOP; END $ddl$;